import{_ as t,o,c as d,a2 as s}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"端到端套件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/e2e-suites.md","filePath":"zh/dev/e2e-suites.md"}'),a={name:"zh/dev/e2e-suites.md"};function r(l,e,c,h,i,p){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="端到端套件" tabindex="-1">端到端套件 <a class="header-anchor" href="#端到端套件" aria-label="Permalink to &quot;端到端套件&quot;">​</a></h1><p>把关发布的深度测试。它们全部通过串口控制台上的 pexpect 驱动 一次真实的 QEMU 启动；下表就是发布证据引用的矩阵（真实输出、 声明的跳过计数）。</p><h2 id="验证矩阵" tabindex="-1">验证矩阵 <a class="header-anchor" href="#验证矩阵" aria-label="Permalink to &quot;验证矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>门禁</th><th>工具</th><th>必须打印的行</th></tr></thead><tbody><tr><td>1</td><td>宿主机单元测试（<code>make test</code>）</td><td><code>tools/run_host_tests.py</code></td><td>所有测试桩 PASS（SKIP-FIXTURE 已声明）</td></tr><tr><td>2</td><td>完整回归 31/31</td><td><code>tools/run_fix4_regression.py</code></td><td><code>=== 31/31 checks passed</code></td></tr><tr><td>3</td><td>SSH E2E</td><td><code>tools/ssh_g11a_e2e.py</code></td><td><code>[g11a] ALL PASS</code>（5 项检查）</td></tr><tr><td>4</td><td>HTTPS E2E</td><td><code>tools/run_fix4_https_e2e.py</code></td><td><code>=== 8/8 HTTPS E2E checks passed</code></td></tr><tr><td>5</td><td>看门狗/日志/健康 E2E</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td><td>S1-S14</td></tr><tr><td>6</td><td>TUI / 中文 / 桌面 E2E</td><td><code>tools/wp10_*.py</code></td><td>按套件</td></tr><tr><td>7</td><td>大应用冒烟</td><td>WP-l1apps-merge 冒烟脚本</td><td>21/21（经典分发 + 向导打开/退出 + 菜单操作 + 更新步骤）</td></tr></tbody></table><h2 id="回归门禁-31-31-tools-run-fix4-regression-py" tabindex="-1">回归门禁（31/31）- tools/run_fix4_regression.py <a class="header-anchor" href="#回归门禁-31-31-tools-run-fix4-regression-py" aria-label="Permalink to &quot;回归门禁（31/31）- tools/run_fix4_regression.py&quot;">​</a></h2><p>启动 ISO，运行命令清单（uname、help -a、经 <code>run</code> 的自检程序）， 并把每条命令的断言模式限定在该命令自己的输出段内（BUG #64： 旧的整日志匹配在结构上恒为真）。它还断言：</p><ul><li><strong>活动的帧缓冲</strong>，通过一次真实的 HMP 截屏（BUG #66 - 仅串口 的门禁曾在一块死面板上通过）；</li><li><strong>注册表下限</strong>：<code>help -a</code> 必须列出 &gt;= 276 个程序（含 8 个 合并应用实测 284）- 接口冻结规则落到可执行层面。</li></ul><h2 id="ssh-e2e-5-5-tools-ssh-g11a-e2e-py" tabindex="-1">SSH E2E（5/5）- tools/ssh_g11a_e2e.py <a class="header-anchor" href="#ssh-e2e-5-5-tools-ssh-g11a-e2e-py" aria-label="Permalink to &quot;SSH E2E（5/5）- tools/ssh_g11a_e2e.py&quot;">​</a></h2><p>在真实 TCP 栈上的客户端与服务器两个方向：ssh-auth、ssh-exec、 sshd-listen、sshd-exec、sshd-capture-log。能帮你省下数小时的 注记：</p><ul><li>TCG RSA-2048 主机密钥生成很慢（&gt;500 s）- 用 mtools 把密钥 （n||d，各 256 B，e=65537）预置进 <code>build/etc.img</code> （<code>ssh_host_key</code>）；加载器会走&quot;密钥已在磁盘上&quot;的快路径。</li><li>在服务器测试前先用一个客户端方向的包暖 ARP 缓存（冷缓存的 SYN-ACK 停摆）。</li></ul><h2 id="https-e2e-8-8-tools-run-fix4-https-e2e-py" tabindex="-1">HTTPS E2E（8/8）- tools/run_fix4_https_e2e.py <a class="header-anchor" href="#https-e2e-8-8-tools-run-fix4-https-e2e-py" aria-label="Permalink to &quot;HTTPS E2E（8/8）- tools/run_fix4_https_e2e.py&quot;">​</a></h2><p>真实 OpenSSL 支撑的测试服务器 + 内核 TLS 客户端：握手、 TLS1.2 + 密码套件协商、加密 GET、规范正文、正文保存、 close_notify、截断守卫（及时检测到硬关闭的服务器）、自签名 证书链拒绝。</p><h2 id="大应用冒烟-21-21" tabindex="-1">大应用冒烟（21/21） <a class="header-anchor" href="#大应用冒烟-21-21" aria-label="Permalink to &quot;大应用冒烟（21/21）&quot;">​</a></h2><p>阶段 A - 经典分发逐字节兼容：每个大应用运行它的一个历史操作 （<code>disk-tool lsblk</code>、<code>net-tool ip</code>、<code>sound-tool sound</code>、 <code>sysdiag health</code>、<code>hwinfo uname</code>、<code>power sleep 1</code>、<code>files df</code>、 <code>update status</code>、<code>disk-tool direct lsblk</code>、未知操作 usage）。</p><p>阶段 B - 向导：每个应用的无参菜单渲染出来并在 <code>q</code> 上退出； <code>disk-tool</code> 经菜单键 1 + ENTER 暂停运行 lsblk；<code>update</code> 真实 走完步骤 1-2（网络检查、A/B 缺盘处理）并干净地回到 ush。</p><h2 id="宿主机单元测试-tools-run-host-tests-py" tabindex="-1">宿主机单元测试 - tools/run_host_tests.py <a class="header-anchor" href="#宿主机单元测试-tools-run-host-tests-py" aria-label="Permalink to &quot;宿主机单元测试 - tools/run_host_tests.py&quot;">​</a></h2><p>测试桩在宿主机侧编译并运行 L0 组件：multiboot2 解析器（ASAN）、 crypto（NIST AES/SHA/HMAC、RSA、X.509、AEAD）、TLS 密钥日程、 TCP 拥塞控制、block-512 门禁、FAT 结构、堆/VMM 不变量…… 当 openssl 夹具存在时，SKIP-FIXTURE 测试桩会真实运行 - 声明 状态即可。</p><h2 id="看门狗-tui-中文套件" tabindex="-1">看门狗 / TUI / 中文套件 <a class="header-anchor" href="#看门狗-tui-中文套件" aria-label="Permalink to &quot;看门狗 / TUI / 中文套件&quot;">​</a></h2><p><code>tools/wp12_watchdog_logging_e2e.py</code>（S12：Intel TCO 真实复位 + 第二次启动；S13：ACPI WDAT；klog 轮转链；策略击杀；健康 JSON）、<code>tools/wp10_tui_e2e.py</code>、<code>wp10_chinese_e2e.py</code>、 <code>wp10_tuiqa_apps_e2e.py</code>、<code>wp10_native_e2e.py</code> - 机制未变， 动到它们的领域时运行它们。</p>',19)])])}const u=t(a,[["render",r]]);export{_ as __pageData,u as default};
